// Photograph manifest for the /photographs section.
// Frames are straight out of a Fujifilm X-M5 in one of six film simulations;
// `lqip` is a 20px JPEG data URI used as the blur-up placeholder.
//
// Every technical field (lens, focal, aperture, shutter, iso, date, sim) is read
// from the file's own EXIF — the film simulation comes from the Fujifilm
// MakerNote FilmMode tag, or from the Saturation tag for the monochrome stocks.
// Place, city, kind and title are editorial.

export type SimId =
  | "all"
  | "classic-chrome"
  | "reala-ace"
  | "astia"
  | "velvia"
  | "nostalgic-neg"
  | "acros";

export type Photo = {
  id: string;
  frame: string;
  src: string;
  lqip: string;
  ratio: number;
  vertical: boolean;
  natW: number;
  natH: number;
  sim: Exclude<SimId, "all">;
  place: string;
  city: string;
  kind: string;
  lens: string;
  focal: string;
  aperture: string;
  shutter: string;
  iso: number;
  date: string;
  title: string;
  body: string;
};

export type Sim = {
  id: SimId;
  name: string;
  short: string;
  accent: string;
  ink: string;
  paper: string;
  filter: string;
  grain: number;
  swatch: string;
  note?: string;
};

/** A photo laid out inside a justified row, with its resolved box. */
export type LaidOutPhoto = Photo & { w: number; h: number };

export type Row = {
  id: string;
  h: number;
  last?: boolean;
  items: LaidOutPhoto[];
};

