export const SIM_MAP: Record<SimId, Sim> = SIMS.reduce(
  (acc, sim) => ({ ...acc, [sim.id]: sim }),
  {} as Record<SimId, Sim>,
);

export function photosFor(sim: SimId): Photo[] {
  return sim === "all" ? PHOTOS : PHOTOS.filter((p) => p.sim === sim);
}

export function countFor(sim: SimId): number {
  return photosFor(sim).length;
}

/**
 * Greedy justified rows: flush left and right, native aspect ratios kept.
 * A row closes as soon as its natural width at `targetH` reaches `width`,
 * then every frame in it is scaled to make the row exactly `width` wide.
 */
export function justify(
  photos: Photo[],
  width: number,
  targetH: number,
  gap: number,
): Row[] {
  const rows: Row[] = [];
  let cur: Photo[] = [];
  let sumR = 0;

  photos.forEach((p) => {
    cur.push(p);
    sumR += p.ratio;
    const need = sumR * targetH + gap * (cur.length - 1);
    if (need >= width) {
      const h = (width - gap * (cur.length - 1)) / sumR;
      rows.push({
        id: "r" + rows.length,
        h,
        items: cur.map((item) => ({ ...item, w: item.ratio * h, h })),
      });
      cur = [];
      sumR = 0;
    }
  });

  if (cur.length) {
    const h = Math.min(targetH, (width - gap * (cur.length - 1)) / sumR);
    rows.push({
      id: "r" + rows.length,
      h,
      last: true,
      items: cur.map((item) => ({ ...item, w: item.ratio * h, h })),
    });
  }

  return rows;
}

